# The bodies for constructs.tsv, one per row, each using its construct and as
# little else as possible. They are here rather than generated by the lane so
# that what is being probed can be read, and so that a row whose body drifted
# from its name is visible.
#
# A body is written between `--- <id>` markers. The lane cuts each one out,
# gives it a contract with two scalars and one buffer, and asks the checker.
#
--- and_op
def probe(a, b, buf, n_buf)
  if a > 0 && b > 0 then 1 else 0 end
end
--- or_op
def probe(a, b, buf, n_buf)
  if a > 0 || b > 0 then 1 else 0 end
end
--- not_op
def probe(a, b, buf, n_buf)
  if !(a > 0) then 1 else 0 end
end
--- modifier_if
def probe(a, b, buf, n_buf)
  c = 0
  c = 1 if a > 0
  c
end
--- unless_no_else
def probe(a, b, buf, n_buf)
  c = a
  c = -c unless a > 0
  c
end
--- ternary
def probe(a, b, buf, n_buf)
  a > 0 ? 1 : 0
end
--- case_when
def probe(a, b, buf, n_buf)
  case a
  when 0 then 1
  else 2
  end
end
--- early_return
def probe(a, b, buf, n_buf)
  return 1 if a > 0
  0
end
--- plain_return
def probe(a, b, buf, n_buf)
  if a > 0
    return 1
  else
    return 0
  end
end
--- until_loop
def probe(a, b, buf, n_buf)
  i = 0
  until i >= 4
    i = i + 1
  end
  i
end
--- break_in_while
def probe(a, b, buf, n_buf)
  i = 0
  while i < 4
    if i == 2
      break
    else
      i = i + 1
    end
  end
  i
end
--- next_in_while
def probe(a, b, buf, n_buf)
  i = 0
  t = 0
  while i < 4
    i = i + 1
    if i == 2
      next
    else
      t = t + i
    end
  end
  t
end
--- helper_scalar
def helper(x)
  x + 1
end

def probe(a, b, buf, n_buf)
  helper(a)
end
--- helper_buffer
def helper(v, n)
  v[0] + n
end

def probe(a, b, buf, n_buf)
  helper(buf, n_buf)
end
--- ivar
def probe(a, b, buf, n_buf)
  @x = a
  @x
end
--- elem_opassign
def probe(a, b, buf, n_buf)
  buf[0] += 1
  buf[0]
end
--- multiple_assign
def probe(a, b, buf, n_buf)
  x, y = a, b
  x + y
end
--- each_block
def probe(a, b, buf, n_buf)
  t = 0
  4.times { |i| t = t + i }
  t
end
--- map_block
def probe(a, b, buf, n_buf)
  buf.map { |x| x + 1 }
  a
end
--- array_literal
def probe(a, b, buf, n_buf)
  xs = [1, 2, 3]
  a
end
--- raise_error
def probe(a, b, buf, n_buf)
  if a < 0
    raise "bad"
  else
    a
  end
end
--- float_lit
def probe(a, b, buf, n_buf)
  c = 2.0
  a + 0
end
--- to_i_call
def probe(a, b, buf, n_buf)
  (a * 2).to_i
end
--- nested_index
def probe(a, b, buf, n_buf)
  buf[buf[0]]
end
--- dispatch_var
def probe2(x)
  x + 1
end

def probe(a, b, buf, n_buf)
  f = :probe2
  send(f, a)
end
--- zero_pred
def probe(a, b, buf, n_buf)
  if a.zero? then 1 else 0 end
end
--- two_stores
def probe(a, b, buf, n_buf)
  buf[0] = a
  buf[1] = b
  0
end
